INSERT INTO exhibition_companies (company_id, name, name_en, tagline, category, park_id, city, description, intro, founders, website, phone, email, address, latitude, longitude, founded_at, headcount_full_time, headcount_part_time, status, is_active, sort_order) VALUES ('kish-fancom-communications', 'ارتباطات فن کام کیش', 'Kish Fancom Communications', 'فراتر از مرزهای ارتباط.', 'telecom', 'alborz', 'گرمدره', 'خدمات مخابراتی و اجرای پروژه‌های زیرساخت ارتباطی', 'این مجموعه متخصص طراحی و اجرای شبکه‌های اختصاصی انتقال داده با پهنای باند بالا برای صنایع نفت، گاز و بانک‌ها است. محصولات سری FON آن‌ها سامانه‌های بومی انتقال نوری مبتنی بر فناوری SDH هستند که ظرفیت‌های چند گیگابیتی را پشتیبانی می‌کنند. این شرکت راهکارهای جامع ارتباطی را برای محیط‌های صنعتی سخت و حساس ارائه می‌دهد.', 'محسن وحدتی', NULL, '88536920', 'info@fancomkish.com', 'تهران، پارک فناوری اطلاعات و ارتباطات', 35.765939700501455, 51.05849012832533, '2013-01-01', 48, '5', 'approved', true, 48);

