INSERT INTO exhibition_companies (company_id, name, name_en, tagline, category, park_id, city, description, intro, founders, website, phone, email, address, latitude, longitude, founded_at, headcount_full_time, headcount_part_time, status, is_active, sort_order) VALUES ('mobin-novel-idea', 'ایده بکر مبین', 'Mobin Novel Idea', 'جایی که ایده‌ها به واقعیت می‌پیوندند.', 'hw', 'alborz', 'گرمدره', 'طراحی پلتفرم‌های دیجیتال و نرم‌افزارهای اختصاصی', 'این شرکت دانش‌بنیان بر تولید پلتفرم‌های تعاملی، اپلیکیشن‌های موبایل و سامانه‌های تحت وب اختصاصی تمرکز دارد. آن‌ها با ارائه راهکارهای نوین در حوزه فناوری اطلاعات، به دیجیتالی‌سازی استارتاپ‌ها و کسب‌وکارهای نوپا کمک می‌کنند. این مجموعه یکی از واحدهای فناور مستقر در پارک‌های علمی و تحقیقاتی معتبر کشور است.', 'محمد شیرین سخن', NULL, '88281228', 'info@ibm.co.ir', 'تهران، پارک فناوری اطلاعات و ارتباطات', 35.765939700501455, 51.05849012832533, '2011-01-01', 42, 4, 'approved', true, 49);

