INSERT INTO exhibition_companies (company_id, name, name_en, tagline, category, park_id, city, description, intro, founders, website, phone, email, address, latitude, longitude, founded_at, headcount_full_time, headcount_part_time, status, is_active, sort_order) VALUES ('arshin-azarmehr-tech', 'آرشین آذر مهر فن‌آور', 'Arshin Azarmehr Tech', 'تبلور دانش در مسیر فناوری.', 'hw', 'alborz', 'گرمدره', 'تلماتیک، ردیابی هوشمند خودرو و ناوبری (GPS)', 'این شرکت دانش‌بنیان متخصص تولید سامانه های ردیابی ماهواره‌ای (GPS) و مدیریت هوشمند ناوگان حمل‌ونقل است. محصولات آن‌ها شامل سخت‌افزارهای ردیابی خودرویی و نرم‌افزارهای مانیتورینگ برای کنترل مصرف سوخت و رفتار رانندگان می‌باشد. آرشین یکی از برندهای مطرح در حوزه تلماتیک و امنیت خودرو در بازار ایران است.', 'حامد واعظی', 'http://arshinits.com/', '021-58431', 'Official@arshinco.com', 'تهران، پارک فناوری اطلاعات و ارتباطات', 35.765939700501455, 51.05849012832533, '2014-01-01', 24, 3, 'approved', true, 50);

-- NEW: آرکا ارتباط امیرکبیر
INSERT INTO exhibition_companies (company_id, name, name_en, tagline, category, park_id, city, description, intro, founders, website, phone, email, address, latitude, longitude, founded_at, headcount_full_time, headcount_part_time, status, is_active, sort_order) VALUES ('amirkabir-arka-communication', 'آرکا ارتباط امیرکبیر', 'Amirkabir Arka Communication', 'اتصالِ امن، فراتر از انتظار.', 'soft', 'alborz', 'گرمدره', 'امنیت شبکه، یکپارچه‌سازی سامانه‌های مخابراتی و دیتاسنتر', 'این مجموعه در زمینه امنیت زیرساخت‌های شبکه، دیتاسنتر و تعمیرات تخصصی بردهای الکترونیک مخابراتی فعالیت می‌کند. آن‌ها خدمات مشاوره و اجرای استانداردهای امنیتی را به سازمان‌های دارای حساسیت بالای داده ارائه می‌دهند. فعالیت اصلی این شرکت در قطب‌های فناوری کرج و تهران متمرکز شده است.', 'امیرحسین رشیدیان', NULL, NULL, 'office@arkacell.com', 'تهران، پارک فناوری اطلاعات و ارتباطات', 35.765939700501455, 51.05849012832533, '2010-01-01', 21, 2, 'approved', true, 51);

