INSERT INTO exhibition_companies (company_id, name, name_en, tagline, category, park_id, city, description, intro, founders, website, phone, email, address, latitude, longitude, founded_at, headcount_full_time, headcount_part_time, status, is_active, sort_order) VALUES ('paya-brilliant-vision', 'آرمان درخشان پایا', 'Paya Brilliant Vision', 'آرمان‌های بزرگ، مسیرهای ماندگار.', 'soft', 'alborz', 'گرمدره', 'صنایع روشنایی، نورپردازی صنعتی و الکترونیک شهری', 'این شرکت دانش‌بنیان در زمینه طراحی و تولید سیستم‌های روشنایی هوشمند و پروژکتورهای فوق‌کم‌مصرف ال‌ای‌دی فعال است. محصولات آن‌ها در پروژه‌های بزرگ نورپردازی شهری و بهینه‌سازی مصرف انرژی در کارخانه‌ها استفاده می‌شود. این مجموعه بر توسعه راهکارهای نوین در صنایع روشنایی با استانداردهای بین‌المللی تمرکز دارد.', 'فربد رزازی', 'info@payasoftco.ir', '026-34092380', 'info@payasoftco.ir', 'تهران، پارک فناوری اطلاعات و ارتباطات', 35.765939700501455, 51.05849012832533, '2016-01-01', 8, 1, 'approved', true, 52);

