INSERT INTO exhibition_companies (company_id, name, name_en, tagline, category, park_id, city, description, intro, founders, website, phone, email, address, latitude, longitude, founded_at, headcount_full_time, headcount_part_time, status, is_active, sort_order) VALUES ('industry-micro-wave', 'بهینه پردازان ریز موج صنعت', 'Industry Micro-Wave Optimizer', 'بهینه‌سازی فردا، از دل امروز.', 'hw', 'alborz', 'گرمدره', 'مخابرات مایکروویو، RF و تجهیزات فرکانس بالا', 'این مجموعه یک شرکت فوق‌تخصصی در طراحی و ساخت قطعات مخابراتی فرکانس بالا و مایکروویو است. فعالیت آن‌ها شامل تولید آنتن‌های خاص و تقویت‌کننده‌های توان برای صنایع پیشرفته مخابراتی و راداری می‌باشد. این شرکت در لبه تکنولوژی مخابرات بی‌سیم و میدان‌های مغناطیسی در کشور فعالیت می‌کند.', NULL, NULL, NULL, NULL, 'تهران، پارک فناوری اطلاعات و ارتباطات', 35.765939700501455, 51.05849012832533, '2013-01-01', 12, 1, 'approved', true, 54);

